/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-sheet {
  box-sizing: border-box;
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-body-size, 14px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-body-line-height, 1.6);
  letter-spacing: var(--ui-type-body-letter-spacing, 0em);
  color: var(--ui-text, #171717);
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  background: var(--ui-surface, #fff);
  box-shadow: var(--ui-shadow, 0 8px 28px #00000016);
  overflow-wrap: anywhere;
}

:where([data-moru-registry]) .ui-sheet {
  position: fixed;
  z-index: 71;
  display: flex;
  flex-direction: column;
  max-width: 100vw;
  max-height: 100dvh;
  /* One scroll surface keeps long headers and footers reachable on short screens. */
  overflow: auto;
  overscroll-behavior: contain;
  --ui-sheet-close-size: var(--ui-control-height-sm, 32px);
  --ui-sheet-gutter: max(
    var(--ui-card-padding, 24px),
    env(safe-area-inset-left),
    env(safe-area-inset-right)
  );
  transition: transform var(--ui-duration, 160ms) ease;
}

:where([data-moru-registry]) .ui-sheet[data-side='left'],
:where([data-moru-registry]) .ui-sheet[data-side='right'] {
  inset-block: 0;
  width: min(440px, 100vw);
  height: 100dvh;
}

:where([data-moru-registry]) .ui-sheet[data-side='left'] {
  inset-inline-start: 0;
  border-radius: 0 var(--ui-radius, 6px) var(--ui-radius, 6px) 0;
}
:where([data-moru-registry]) .ui-sheet[data-side='right'] {
  inset-inline-end: 0;
  border-radius: var(--ui-radius, 6px) 0 0 var(--ui-radius, 6px);
}
:where([data-moru-registry]) .ui-sheet[data-side='bottom'] {
  inset-inline: 0;
  inset-block-end: 0;
  width: 100%;
  max-height: min(85dvh, 800px);
  border-radius: var(--ui-radius, 6px) var(--ui-radius, 6px) 0 0;
}

:where([data-moru-registry]) .ui-sheet[data-side='right'][data-starting-style],
:where([data-moru-registry]) .ui-sheet[data-side='right'][data-ending-style] {
  transform: translateX(100%);
}
:where([data-moru-registry]) .ui-sheet[data-side='left'][data-starting-style],
:where([data-moru-registry]) .ui-sheet[data-side='left'][data-ending-style] {
  transform: translateX(-100%);
}
:where([data-moru-registry]) .ui-sheet[data-side='bottom'][data-starting-style],
:where([data-moru-registry]) .ui-sheet[data-side='bottom'][data-ending-style] {
  transform: translateY(100%);
}
:where([data-moru-registry]) .ui-sheet:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: -3px;
}

:where([data-moru-registry]) .ui-sheet-header {
  flex: none;
  padding-block: max(var(--ui-card-padding, 24px), env(safe-area-inset-top))
    var(--ui-card-padding, 24px);
  padding-inline: var(--ui-sheet-gutter)
    calc(var(--ui-sheet-gutter) + var(--ui-sheet-close-size) + var(--ui-control-gap, 8px));
  border-bottom: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
}

:where([data-moru-registry]) .ui-sheet-close {
  position: absolute;
  inset-block-start: max(var(--ui-card-padding, 24px), env(safe-area-inset-top));
  inset-inline-end: var(--ui-sheet-gutter);
  width: var(--ui-sheet-close-size);
  height: var(--ui-sheet-close-size);
}

:where([data-moru-registry]) .ui-sheet-content {
  min-height: 0;
  min-width: 0;
  flex: 1 0 auto;
  padding: var(--ui-card-padding, 24px) var(--ui-sheet-gutter);
}
:where([data-moru-registry]) .ui-sheet-content > :first-child {
  margin-block-start: 0;
}
:where([data-moru-registry]) .ui-sheet-content > :last-child {
  margin-block-end: 0;
}
:where([data-moru-registry]) .ui-sheet-footer {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: var(--ui-control-gap, 8px);
  padding: var(--ui-card-padding, 24px) var(--ui-sheet-gutter);
  padding-block-end: max(var(--ui-card-padding, 24px), env(safe-area-inset-bottom));
  border-top: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
}
:where([data-moru-registry]) .ui-sheet-footer > .ui-button {
  max-width: 100%;
  height: auto;
  white-space: normal;
  overflow-wrap: anywhere;
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-sheet {
    --ui-sheet-close-size: max(44px, var(--ui-control-height-sm, 32px));
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-sheet {
    transition: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import type { ComponentPropsWithoutRef, ReactElement, ReactNode } from 'react'
import { Dialog as BaseDialog } from '@base-ui/react/dialog'
import { X } from 'lucide-react'
import { cn } from './_lib/cn'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './overlay-shared.css'
import './sheet.css'

export interface SheetProps {
  trigger?: ReactElement
  title: string
  description?: string
  children?: ReactNode
  footer?: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  side?: 'left' | 'right' | 'bottom'
  className?: string
  initialFocus?: ComponentPropsWithoutRef<typeof BaseDialog.Popup>['initialFocus']
  finalFocus?: ComponentPropsWithoutRef<typeof BaseDialog.Popup>['finalFocus']
}

/** A modal edge panel; Base UI handles focus trapping, Escape, and scroll locking. */
export function Sheet({
  trigger,
  title,
  description,
  children,
  footer,
  open,
  defaultOpen,
  onOpenChange,
  side = 'right',
  className,
  initialFocus,
  finalFocus,
}: SheetProps) {
  const { t } = useI18n()

  const portalContainer = useThemePortalContainer()
  return (
    <BaseDialog.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={(nextOpen) => onOpenChange?.(nextOpen)}
    >
      {trigger && <BaseDialog.Trigger render={trigger} />}
      <OverlayPortal portal={BaseDialog.Portal} kind="modal" container={portalContainer}>
        <BaseDialog.Backdrop className="ui-overlay-backdrop" />
        <BaseDialog.Popup
          className={cn('ui-sheet', className)}
          data-side={side}
          initialFocus={initialFocus}
          finalFocus={finalFocus}
        >
          <div className="ui-sheet-header">
            <BaseDialog.Title className="ui-overlay-title">{title}</BaseDialog.Title>
            {description && (
              <BaseDialog.Description className="ui-overlay-description">
                {description}
              </BaseDialog.Description>
            )}
          </div>
          <BaseDialog.Close className="ui-overlay-close ui-sheet-close" aria-label={t('패널 닫기')}>
            <X size={18} aria-hidden="true" />
          </BaseDialog.Close>
          <div className="ui-sheet-content">{children}</div>
          {footer && <div className="ui-sheet-footer">{footer}</div>}
        </BaseDialog.Popup>
      </OverlayPortal>
    </BaseDialog.Root>
  )
}
